backup_html='''  <div id="settingsSubnav" class="settingsSubnav" role="tablist" aria-label="Settings sections"><button id="settingsGeneralTab" class="btn active" type="button" role="tab" aria-selected="true">System</button><button id="backupSettingsTab" class="btn" type="button" role="tab" aria-selected="false">Backup &amp; Restore</button></div>\n    <div id="backupSettingsPanel" class="panel" hidden>\n      <strong>Settings Backup</strong><div class="sub">Automatically backs up the selected settings once a week. You can also back up or restore manually at any time.</div>\n      <div class="backupChoiceGrid">\n        <label class="backupChoice"><input id="backupSchedule" type="checkbox"><span><strong>Schedules</strong><br><span class="sub">Times, rules, holiday calendar</span></span></label>\n        <label class="backupChoice"><input id="backupControllers" type="checkbox"><span><strong>Controllers</strong><br><span class="sub">BLE controller setup</span></span></label>\n        <label class="backupChoice"><input id="backupCustom" type="checkbox"><span><strong>Custom Lights</strong><br><span class="sub">Shows and custom schedules</span></span></label>\n        <label class="backupChoice"><input id="backupFavorites" type="checkbox"><span><strong>Favorite Colors</strong><br><span class="sub">Saved calibrated palette values</span></span></label>\n        <label class="backupChoice"><input id="backupEvents" type="checkbox"><span><strong>Events</strong><br><span class="sub">Enabled, favorites, event edits</span></span></label>\n      </div>\n      <div id="backupStatusCard" class="card small" style="margin-top:10px">Loading backup status…</div>\n      <button id="saveBackupSelection" class="btn" type="button" style="width:100%;margin-top:9px">Save Backup Selection</button>\n      <button id="backupNow" class="btn primary" type="button" style="width:100%;margin-top:9px">Back Up Now</button>\n      <button id="restoreBackup" class="btn" type="button" style="width:100%;margin-top:9px" disabled>Restore Last Good Backup</button>\n      <div class="note">Backups use two verified generations in the existing persistent storage partition. A failed backup cannot replace the last good backup. Restore prevalidates the complete snapshot and keeps a recovery copy until the restore commits.</div>\n    </div>\n'''
