backup_js=r'''let settingsSubtab='main',settingsBackupState=null;
function settingsBackupMaskFromUi(){let m=0;if($('backupSchedule')?.checked)m|=1;if($('backupControllers')?.checked)m|=2;if($('backupCustom')?.checked)m|=4;if($('backupFavorites')?.checked)m|=8;if($('backupEvents')?.checked)m|=16;return m}
function settingsBackupTime(v){const n=Number(v||0);if(!n)return 'Never';try{return new Date(n*1000).toLocaleString()}catch(e){return String(n)}}
function showSettingsSubtab(which){settingsSubtab=which==='backup'?'backup':'main';const page=document.querySelector('.page[data-page="settings"]'),backup=$('backupSettingsPanel');if(!page||!backup)return;Array.from(page.children).forEach(el=>{if(el.classList?.contains('panel'))el.hidden=settingsSubtab==='backup'?el!==backup:el===backup});const g=$('settingsGeneralTab'),b=$('backupSettingsTab');if(g){g.classList.toggle('active',settingsSubtab==='main');g.setAttribute('aria-selected',settingsSubtab==='main'?'true':'false')}if(b){b.classList.toggle('active',settingsSubtab==='backup');b.setAttribute('aria-selected',settingsSubtab==='backup'?'true':'false')}if(settingsSubtab==='backup')loadSettingsBackupStatus()}
async function loadSettingsBackupStatus(){if(currentRole!=='admin'&&currentRole!=='jason'){}try{const d=await api('/api/backup/status');settingsBackupState=d;const mask=Number(d.mask||0);[['backupSchedule',1],['backupControllers',2],['backupCustom',4],['backupFavorites',8],['backupEvents',16]].forEach(([id,bit])=>{const el=$(id);if(el)el.checked=!!(mask&bit)});const parts=[];parts.push(`<strong>${d.hasBackup?'Last good backup available':'No completed backup yet'}</strong>`);parts.push(`Last successful: ${settingsBackupTime(d.lastBackup)}`);parts.push(`Last automatic: ${settingsBackupTime(d.lastAutomatic)}`);parts.push(`Next weekly backup: ${d.nextAutomatic?settingsBackupTime(d.nextAutomatic):'As soon as time is synchronized'}`);if(d.retryAfter)parts.push(`Failure retry: ${settingsBackupTime(d.retryAfter)}`);if(d.restorePending)parts.push('<b>Restore recovery is pending and will be completed before normal operation.</b>');parts.push(`Storage: ${d.storageReady===false?'Unavailable':(d.backend||'Persistent storage')}`);$('backupStatusCard').innerHTML=parts.join('<br>');$('restoreBackup').disabled=!d.hasBackup;$('backupNow').disabled=!mask||d.storageReady===false}catch(e){$('backupStatusCard').textContent='Backup status unavailable: '+e.message}}
'''
